package com.smarthub.plus;
import org.junit.Test;import org.json.*;import java.time.*;import static org.junit.Assert.*;
public class FactoryProtocolTest {
 @Test public void receiverChallengeMatchesIndependentDesEdeVector()throws Exception{assertEquals("515e4c956d689078117ecbfc9e57864f",FactoryProtocol.authenticator("TEST00000001","TEST00000001"));}
 @Test public void httpsOriginsAreCanonicalAndCredentialFree()throws Exception{assertEquals("https://factory.example",FactoryProtocol.origin("https://factory.example/"));for(String s:new String[]{"http://factory.example","https://user:password@factory.example","https://127.0.0.1","https://factory.example/token","https://factory.example?key=value"})try{FactoryProtocol.origin(s);fail(s);}catch(Exception expected){}}
 @Test public void discoverySelectsOnlyTheDefaultFactoryServer()throws Exception{JSONObject j=new JSONObject("{code:0,data:[{domain:'https://other.example',isDefault:false},{domain:'https://factory.example',isDefault:true}]}");assertEquals("https://factory.example",FactoryProtocol.domain(j));}
 @Test public void localEpgTimeHonoursReceiverTimezone(){assertEquals(Instant.parse("2026-11-01T12:00:00Z").toEpochMilli(),FactoryProtocol.time("2026-11-01 15:00:00",ZoneId.of("Asia/Baghdad")));}
 @Test public void isoAndEpochTimesAreAccepted(){assertEquals(1760000000000L,FactoryProtocol.time("1760000000",ZoneOffset.UTC));assertEquals(Instant.parse("2026-11-01T12:00:00Z").toEpochMilli(),FactoryProtocol.time("2026-11-01T15:00:00+03:00",ZoneOffset.UTC));assertEquals(0,FactoryProtocol.time("not-a-date",ZoneOffset.UTC));}
 @Test public void remakesAndOtherEpisodesCannotMatch(){assertFalse(FactoryProtocol.sameTitle("Gold (2022)","Gold (2016)"));assertFalse(FactoryProtocol.sameTitle("Film S01E02","Film S01E03"));assertTrue(FactoryProtocol.sameTitle("Film S01E02","Film"));}
 @Test public void emptyNamesAndUnsafePicturesAreRejected(){assertFalse(FactoryProtocol.sameTitle("",""));assertEquals("",FactoryProtocol.image("file:///data/private.png"));assertEquals("",FactoryProtocol.image("https://user:password@example.org/a.png"));assertEquals("https://images.example.org/a.png",FactoryProtocol.image("https://images.example.org/a.png"));}
 @Test public void actualScheduleWireFieldsKeepPosterAndSubtitleSeparate()throws Exception{JSONObject j=new JSONObject("{code:0,data:{root:[{list:[{name:'A',start:'2026-11-01 10:00:00',end:'2026-11-01 11:00:00',pic:'https://images.example.org/poster.jpg',subtitle:'Episode 1'}]}]}}");java.util.List<FactoryProtocol.Event> list=FactoryProtocol.schedule(j,ZoneOffset.UTC);assertEquals(1,list.size());assertEquals("Episode 1",list.get(0).subtitle);assertTrue(list.get(0).pic.endsWith("poster.jpg"));}
 @Test public void invalidTimeWindowsAreNotPublished()throws Exception{JSONObject j=new JSONObject("{code:0,data:{root:[{list:[{name:'A',start:'2026-11-01 11:00:00',end:'2026-11-01 10:00:00'}]}]}}");assertTrue(FactoryProtocol.schedule(j,ZoneOffset.UTC).isEmpty());}
 @Test public void duplicatedChannelNamesNeedAProgrammeMatch()throws Exception{JSONObject j=new JSONObject("{code:0,data:{channelList:[{id:'A',name:'HBO2 HD'},{id:'B',name:'HBO2 HD'}]}}");assertEquals("",FactoryProtocol.channelKey(j,"HBO2 HD","Film",1,ZoneOffset.UTC));assertEquals("",FactoryProtocol.channelKey(j,"HBO HD","Film",1,ZoneOffset.UTC));}
 @Test public void uniqueExactChannelCanBeResolved()throws Exception{JSONObject j=new JSONObject("{code:0,data:{channelList:[{id:'A',name:'HBO2 HD'}]}}");assertEquals("A",FactoryProtocol.channelKey(j,"HBO2 HD","Film",1,ZoneOffset.UTC));}
 @Test public void serviceOriginsAreBoundToVerifiedDiscovery()throws Exception{JSONObject j=new JSONObject("{code:0,data:[{domain:'https://data.example',isDefault:true},{domain:'https://epg.example',isDefault:false},{domain:'https://data.example',isDefault:false}]}");JSONArray hosts=FactoryProtocol.origins(j);assertEquals(2,hosts.length());JSONObject saved=new JSONObject().put("host",FactoryProtocol.domain(j)).put("serviceOrigins",hosts);assertTrue(FactoryProtocol.allowedOrigin(saved,"https://epg.example"));assertFalse(FactoryProtocol.allowedOrigin(saved,"https://other.example"));assertFalse(FactoryProtocol.allowedOrigin(saved,"http://epg.example"));}
 @Test public void scheduleReferenceUsesActualSatelliteTransponderAndSid()throws Exception{JSONObject search=new JSONObject("{data:{channelList:[{id:42,name:'HBO2 HD',satellite:'130'}]}}");JSONObject catalogue=new JSONObject("{code:0,data:[{sat:'130',tps:[{tp:12345,sids:[{id:41,sid:10},{id:42,sid:11}]}]}]}");assertEquals("130:12345:11",FactoryProtocol.resolveReference(search,"42",catalogue));assertEquals("",FactoryProtocol.resolveReference(search,"42",null));assertFalse(FactoryProtocol.reference("42"));}
 @Test public void ambiguousCatalogueCannotBindAnotherTransponder()throws Exception{JSONObject search=new JSONObject("{data:{channelList:[{id:42,satellite:'130'}]}}");JSONObject catalogue=new JSONObject("{code:0,data:[{sat:'130',tps:[{tp:12345,sids:[{id:42,sid:11}]},{tp:12456,sids:[{id:42,sid:12}]}]}]}");assertEquals("",FactoryProtocol.resolveReference(search,"42",catalogue));}
}
